import path from 'node:path'
import ts from 'typescript'

// Include the changed entry points and resolve all of their real imports. Do
// not depend on .next route files being regenerated by a concurrent build.
const cwd = process.cwd()
const configPath = path.join(cwd, 'tsconfig.json')
const config = ts.readConfigFile(configPath, ts.sys.readFile)
if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'))
const parsed = ts.parseJsonConfigFileContent({
  ...config.config,
  files: [
    'app/api/voice-companion/session/route.ts',
    'lib/voice-companion/gemini-live-client.ts',
    'lib/media/feedback.ts',
    'components/navigation/jarvis-top-nav-filament.tsx',
    'scripts/diagnose-jarvis-connection.mts',
  ],
  include: [],
}, ts.sys, cwd)
const program = ts.createProgram(parsed.fileNames, { ...parsed.options, incremental: false, noEmit: true })
const diagnostics = [...parsed.errors, ...ts.getPreEmitDiagnostics(program)]
if (diagnostics.length) {
  console.error(ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCanonicalFileName: name => name,
    getCurrentDirectory: () => cwd,
    getNewLine: () => '\n',
  }))
  process.exit(1)
}
console.log('Jarvis connection types passed')
